import{_ as i,o as a,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"NeoMorphix UIX","description":"English short note for the NeoMorphix UIX Home Assistant theme.","frontmatter":{"title":"NeoMorphix UIX","description":"English short note for the NeoMorphix UIX Home Assistant theme."},"headers":[],"relativePath":"en/collection/neomorphix-uix/index.md","filePath":"en/collection/neomorphix-uix/index.md","lastUpdated":1793123188000}'),o={name:"en/collection/neomorphix-uix/index.md"};function s(n,e,l,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[r(`<p><a id="current-focus"></a></p><h1 id="neomorphix-uix" tabindex="-1">NeoMorphix UIX <a class="header-anchor" href="#neomorphix-uix" aria-label="Permalink to &quot;NeoMorphix UIX {#neomorphix-uix}&quot;">​</a></h1><p>NeoMorphix UIX is a UIX variant of the NeuMorphix Home Assistant theme. It relies on soft shadows, round surfaces and a slightly three-dimensional look for dashboards.</p><div class="warning custom-block"><p class="custom-block-title">Unofficial note</p><p>This page is not official documentation of the project. It summarizes the most important installation and usage instructions in English. The original repository remains authoritative.</p></div><table tabindex="0"><thead><tr><th>field</th><th>Value</th></tr></thead><tbody><tr><td>Original project</td><td><a href="https://github.com/yakidd/NeumorphixHome" target="_blank" rel="noreferrer">yakidd/NeumorphixHome</a></td></tr><tr><td>Verified commit</td><td><a href="https://github.com/yakidd/NeumorphixHome/commit/269c298e47b02faaac4f08c8c9dfccf49d70d860" target="_blank" rel="noreferrer"><code>269c298e47b02faaac4f08c8c9dfccf49d70d860</code></a></td></tr><tr><td>Release</td><td><a href="https://github.com/yakidd/NeumorphixHome/releases/tag/1.0.3" target="_blank" rel="noreferrer"><code>1.0.3</code></a></td></tr><tr><td>UIX fork</td><td><a href="https://github.com/rockbaer2007/NeoMorphix-UIX/tree/experiment/uix-theme-variant" target="_blank" rel="noreferrer">rockbaer2007/NeoMorphix-UIX</a></td></tr><tr><td>License</td><td>according to README: WITH</td></tr><tr><td>Category</td><td>HA Dashboard -&gt; Themes</td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation {#installation}&quot;">​</a></h2><p>NeoMorphix UIX is based on NeuMorphix and is prepared as a HACS theme variant.</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=NeoMorphix-UIX&amp;category=theme" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Open NeoMorphix UIX in HACS"></a></p><ol><li>Install HACS if not already installed.</li><li><a href="https://uix.lf.technology/quick-start/" target="_blank" rel="noopener noreferrer">UIX Install</a>.</li><li>Install the NeoMorphix UIX fork as a theme via HACS.</li><li>Restart Home Assistant.</li><li>Select a NeoMorphix UIX variant in the user profile or dashboard settings.</li></ol><p>The theme integration must be active for Home Assistant:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  themes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!include_dir_merge_named</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The original NeuMorphix version uses card-mod. NeoMorphix UIX requires UIX instead.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  themes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!include_dir_merge_named</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="varianten" tabindex="-1">Variants <a class="header-anchor" href="#varianten" aria-label="Permalink to &quot;Variants {#varianten}&quot;">​</a></h2><p>The original project provides two theme files:</p><ul><li><code>themes/neumorphix.yaml</code></li><li><code>themes/neumorphix-inset.yaml</code></li></ul><p>This includes six theme variants:</p><ul><li><code>neumorphix-light</code></li><li><code>neumorphix-dark</code></li><li><code>neumorphix-claude</code></li><li><code>neumorphix-light-inset</code></li><li><code>neumorphix-dark-inset</code></li><li><code>neumorphix-claude-inset</code></li></ul><p><code>Raised</code> acts like a raised surface. <code>Inset</code> appears to be pressed in or embedded in the surface.</p><h2 id="uix-variante" tabindex="-1">UIX variant <a class="header-anchor" href="#uix-variante" aria-label="Permalink to &quot;UIX variant {#uix-variante}&quot;">​</a></h2><p>A supplementary branch was created for UIX, which does not replace the original card-mod files, but adds additional UIX theme files:</p><ul><li><a href="https://github.com/rockbaer2007/NeoMorphix-UIX/tree/experiment/uix-theme-variant" target="_blank" rel="noreferrer">UIX branch in fork</a></li><li><a href="https://github.com/yakidd/NeumorphixHome/pull/4" target="_blank" rel="noreferrer">Pull Request to Original Project</a></li></ul><p>The UIX branch adds:</p><ul><li><code>themes/NeoMorphix UIX.yaml</code></li><li><code>themes/NeoMorphix UIX Inset.yaml</code></li></ul><p>The additional theme names are:</p><ul><li><code>NeoMorphix UIX Light</code></li><li><code>NeoMorphix UIX Dark</code></li><li><code>NeoMorphix UIX Claude</code></li><li><code>NeoMorphix UIX Light Inset</code></li><li><code>NeoMorphix UIX Dark Inset</code></li><li><code>NeoMorphix UIX Claude Inset</code></li></ul><p>Technically, the additional files were mapped to UIX theme keys:</p><ul><li><code>card-mod-theme</code> -&gt; <code>uix-theme</code></li><li><code>card-mod-root-yaml</code> -&gt; <code>uix-root-yaml</code></li><li><code>card-mod-sidebar-yaml</code> -&gt; <code>uix-drawer-yaml</code></li></ul><h2 id="hinweise" tabindex="-1">Notes <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Notes {#hinweise}&quot;">​</a></h2><ul><li>The original project lists MIT as a license in the README, but does not have a separate <code>LICENSE</code> file in the repository.</li><li>The UIX variant is intended as a supplement. The existing card mod files remain unchanged.</li><li>With the inset variants, the main settings page of Home Assistant may react differently because this interface is rendered differently than normal dashboards.</li></ul>`,30)])])}const u=i(o,[["render",s]]);export{m as __pageData,u as default};
